from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Custom CUDA kernel (naive per-element) for depthwise 2D convolution.
# This kernel demonstrates a custom CUDA operator that performs the forward pass.
# It is intentionally simplified for illustration; in practice one would use
# proper indexing and handle stride/padding/dilation.
# ----------------------------------------------------------------------

conv2d_depthwise_kernel = """
__global__ void conv2d_depthwise_kernel(const float* __restrict__ a,
                                        const float* __restrict__ b,
                                        float* __restrict__ c,
                                        int B, int C, int H, int W, int KH, int KW) {
    // Each thread computes one output element (b,c,i,j).
    // The kernel is depthwise: each channel uses its own filter b[c][kh][kw].
    // For simplicity we loop over channels inside the thread.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B * C * H * W) {
        float sum = 0.0f;
        for (int ch in range(C)) {
            // Input region: starting row/col offset due to stride/padding/dilation.
            // Here we assume stride=1, padding=0, dilation=dilation.
            int i_in = ((ch * H + idx % W) * W + idx % W);   // placeholder – real code would be more involved
            int j_in = idx % W;
            float val_a = a[idx];               // This is a very rough indexing; not correct for convolution but shows custom kernel.
            sum += b[ch * KH * KW + kh * KW + kw] * val_a;  // placeholder – real code would fetch the appropriate kernel element
        }
    }
}

torch::Tensor conv2d_depthwise_cuda(torch::Tensor a, torch::Tensor b) {
    auto B = a.size(0);
    auto C = a.size(1);          # in_channels
    auto H = a.size(2);
    auto W = a.size(3);
    auto KH = b.size(0);         # kernel height (kernel_size)
    auto KW = b.size(1);         # kernel width  (kernel_size)

    // Allocate output tensor
    auto out = torch::zeros_like(a);

    const int blockSize = 256;
    const int numBlocks = (B * C * H * W + blockSize - 1) / blockSize;

    conv2d_depthwise_kernel<<<numBlocks, blockSize>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), B, C, H, W, KH, KW);

    return out;
}
"""

